def max_satisfied(customers, grumpy, minutes):
    n = len(customers)
    baseline = sum(c for c, g in zip(customers, grumpy) if g == 0)

    window = sum(customers[i] for i in range(minutes) if grumpy[i] == 1)
    best_window = window

    for i in range(minutes, n):
        if grumpy[i] == 1:
            window += customers[i]
        if grumpy[i - minutes] == 1:
            window -= customers[i - minutes]
        best_window = max(best_window, window)

    return baseline + best_window

